  if (u.usedUp !== 1024 || u.quotaUsedBytes !== 2048) throw new Error("weighted quota usage was not tracked separately");
  store.updateUser(u.id, { usageFactor: 1.5 });
  if (u.quotaUsedBytes !== 2048) throw new Error("changing the factor retroactively altered quota usage");
  store.recordTraffic(u, "down", 1024);
  if (u.usedDown !== 1024 || u.quotaUsedBytes !== 3584) throw new Error("new factor was not applied to future traffic");
  u.volumeBytes = 3000;
  if (store.isActive(u)) throw new Error("weighted quota not enforced");
